static_assert(sizeof(OnlineBackend) == 0x1060, "the C OnbBe layout");

// a log line of 120 characters at most
struct RoomLine {
    char text[120];
    int n = 0;
    void add(const char *t) {
        while (*t && n < 120) text[n++] = *t++;
    }
    void name(const char *t, int limit) {   // a member name: 16 characters, while fewer than `limit` are used
        for (int q = 0; q < 16 && t[q] && n < limit; ++q) text[n++] = t[q];
    }
    void dec(uint32_t v) {
        char digits[12];
        int k = 0;
        do digits[k++] = static_cast<char>('0' + v % 10);
        while (v /= 10);
        while (k && n < 120) text[n++] = digits[--k];
    }
    const char *done() {
        text[n] = 0;
        return text;
    }
};









