void u3x_kickback_icons(uintptr_t base, void *s, int32_t *ev, int32_t row, int coop, uint32_t user, uint8_t *profile,
                        int32_t loadout);
uint8_t *u3x_kickback_nth(void *s, int32_t n, int coop);
