constexpr uint32_t ST_FLAG_1000000 = 0xcd644ff7;
constexpr uint32_t ST_FLAG_2000_COUNT = 0xa622ff01;
constexpr uint32_t ST_FLAG_10000 = 0xe5ad0b24;
