constexpr uint32_t MSG_MATCHMAKING_STARTS = 0x118;
constexpr uint32_t NET_STATE_MATCHMAKING_STARTS = 20;

// ---- game data (image offsets)
constexpr uintptr_t G_CLOCK = 0x17b4ba4;
