int u3x_k23_callees(uintptr_t base);
void u3x_k23_update(uintptr_t base, uint8_t *el);
int u3h_k26_draw(uintptr_t b, void *el, void *rbp);
// this group
int32_t u3x_cin_icon_index(uintptr_t base, uint32_t id, int which);
